"""Compile independent original and C peer callers for all moved forwarding operations."""
from pathlib import Path
root=Path(__file__).resolve().parents[2];out=root/'.diagnostics/sprite-c-tests';probe=out/'runtime'
for original in [True,False]:
    # Exercise the real before/after private peer APIs using their own coherent headers
    text=('#include "owners.h"\n#include "original-Sprite.h"\n' if original else '#include "Sprite.h"\n')+'#include "Clouds_backend.h"\n#include "PointLights_backend.h"\n#include "MoneyMessages_backend.h"\n#include "ScrollBar_backend.h"\n#include "sprite-entry.h"\n'
    text+='static SpriteArgs *activePeerArgs;\nstatic void peerPoints(ScrollBar *bar,ScrollBarPoints points,uint8_t r,uint8_t g,uint8_t b)\n{\n    // Initialize each live point before projection and expose only defined values during the synchronous callback\n    (void)bar;*points.input.x=activePeerArgs->f[SF_x];*points.input.y=activePeerArgs->f[SF_y];*points.input.z=activePeerArgs->f[SF_z];*points.output.x=-101;*points.output.y=-102;*points.output.z=-103;float width=-104,height=-105;bool visible=ScrollBar_BackendProject('+('points.input.owner,points.output.owner' if original else 'points.input,points.output')+',&width,&height,true);(void)visible;(void)r;(void)g;(void)b;FixturePoints(points.input.x,points.input.y,points.input.z,points.output.x,points.output.y,points.output.z,points.input.owner,points.output.owner);\n}\nvoid TestSpritePeers(unsigned operation,SpriteArgs *args,SpriteResult *result)\n{\n    // Forward exact original scalar arguments to each complete native or C peer definition\n    float x=args->f[SF_x],y=args->f[SF_y],z=args->f[SF_z],w=args->f[SF_w],h=args->f[SF_h],reciprocal=args->f[SF_recipz],rotation=args->f[SF_rotation];uint8_t r=args->bytes[0],g=args->bytes[1],b=args->bytes[2],alpha=args->bytes[3];int16_t intensity=args->intensity;result->value=0;result->visible=false;switch(operation){\n'
    for name,kind,inp,outp in [('Cloud','CloudsVector','value','out'),('Light','PointLightsVector','coors','screen'),('Money','MoneyMessageVector','position','out')]:
        # Preserve the distinct copied-output rule of each original projection forwarding interface
        function={'Cloud':'Clouds_BackendProject','Light':'PointLights_BackendScreen','Money':'MoneyMessages_BackendProject'}[name];text+='case SP_Peer'+name+'Project:{'+kind+' input={*args->input[0],*args->input[1],*args->input[2]},output={*args->output[0],*args->output[1],*args->output[2]};result->visible='+function+'(input,&output,args->width,args->height,args->farclip);*args->output[0]=output.x;*args->output[1]=output.y;*args->output[2]=output.z;break;}\n'
    text+='case SP_PeerScrollProject:{ScrollBarPoint input={args->inputOwner,args->input[0],args->input[1],args->input[2]},output={args->outputOwner,args->output[0],args->output[1],args->output[2]};result->visible=ScrollBar_BackendProject('+('input.owner,output.owner' if original else 'input,output')+',args->width,args->height,args->farclip);break;}\n'
    text+='case SP_PeerScrollPoints:{SpriteArgs *previous=activePeerArgs;activePeerArgs=args;ScrollBar_BackendWithPoints(NULL,r,g,b,peerPoints);activePeerArgs=previous;break;}\n'
    simple={'PeerCloudInit':'Clouds_BackendInitSprites','PeerCloudFlush':'Clouds_BackendFlushSprites','PeerLightInit':'PointLights_BackendSpriteInit','PeerLightFlush':'PointLights_BackendSpriteFlush','PeerScrollInit':'ScrollBar_BackendInitSprites','PeerScrollFlush':'ScrollBar_BackendFlushSprites'}
    for op,function in simple.items():text+='case SP_'+op+':'+function+'();break;\n'
    render={'PeerCloudOne':('Clouds_BackendRenderOneXLUSprite',False),'PeerCloudBuffered':('Clouds_BackendRenderBufferedOneXLUSprite',False),'PeerCloudDimension':('Clouds_BackendRenderBufferedOneXLUSprite_Rotate_Dimension',True),'PeerCloudAspect':('Clouds_BackendRenderBufferedOneXLUSprite_Rotate_Aspect',True),'PeerLightSprite':('PointLights_BackendSprite',True),'PeerScrollSprite':('ScrollBar_BackendSprite',False)}
    for op,(function,rotate) in render.items():text+='case SP_'+op+':'+function+'(x,y,z,w,h,r,g,b,intensity,reciprocal'+(',rotation' if rotate else '')+',alpha);break;\n'
    text+='case SP_PeerCloudColours:Clouds_BackendRenderBufferedOneXLUSprite_Rotate_2Colours(x,y,z,w,h,r,g,b,args->bytes[4],args->bytes[5],args->bytes[6],args->f[SF_cx],args->f[SF_cy],reciprocal,rotation,alpha);break;\n}}\n'
    (probe/('before-peers.cpp' if original else 'after-peers.c')).write_text(text,newline='\n')
